using System;
using System.IO;
using System.Drawing;
using System.Collections.Generic;
using System.Windows.Forms;

namespace LoopPedal {
partial class Pedal {
 readonly MidiMap midiMap=new MidiMap();readonly Dictionary<string,Button> midiButtons=new Dictionary<string,Button>();MidiInput midiInput;Form midiWindow;Label midiInfo;StudioChoice midiTarget;bool midiReady;
 string MidiPath{get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Agent-Looper-MIDI.xml");}}
 void InitMidi(){midiMap.Trigger=action=>{Button b;if(midiButtons.TryGetValue(action,out b))b.PerformClick();};midiMap.Learned=action=>{SaveMidi();if(midiInfo!=null&&!midiInfo.IsDisposed)midiInfo.Text=action+" · "+midiMap.Bindings[action];status.Text="MIDI · "+action+" · "+midiMap.Bindings[action];};try{if(File.Exists(MidiPath))midiMap.Load(MidiPath);else{string legacy=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Strata-MIDI.xml");if(File.Exists(legacy))midiMap.Load(legacy);}if(!previewMode&&!string.IsNullOrEmpty(midiMap.DeviceName)){int device=Array.IndexOf(MidiInput.Names(),midiMap.DeviceName);if(device>=0)midiInput=new MidiInput(device);}}catch(Exception e){status.Text=e.Message;}midiReady=true;}
 void PollMidi(){if(!midiReady||midiInput==null)return;int packed,limit=128;while(limit-->0&&midiInput.TryRead(out packed))midiMap.Handle(packed);}
 void SaveMidi(){try{midiMap.Save(MidiPath);}catch(Exception e){status.Text="MIDI settings · "+e.Message;}}
 void RegisterMidi(string action,Button button){midiButtons[action]=button;button.AccessibleDescription="Right-click for MIDI Learn";var menu=new ContextMenuStrip{Renderer=new StudioMenuRenderer(),ShowImageMargin=false,BackColor=Skin.Ink,ForeColor=Color.WhiteSmoke};menu.Items.Add("MIDI Learn",null,(s,e)=>LearnMidi(action));menu.Items.Add("Clear MIDI",null,(s,e)=>{midiMap.Bindings.Remove(action);if(midiMap.LearnTarget==action)midiMap.LearnTarget=null;SaveMidi();status.Text="MIDI cleared · "+action;});button.ContextMenuStrip=menu;}
 void LearnMidi(string action){midiMap.LearnTarget=action;midiMap.ResetEdges();if(midiInput==null){ShowMidi();if(midiTarget!=null)midiTarget.SelectedItem=action;}if(midiInfo!=null&&!midiInfo.IsDisposed)midiInfo.Text="LEARNING · "+action;status.Text="MIDI LEARN · "+action;}
 void ShowMidi(){if(midiWindow!=null&&!midiWindow.IsDisposed){midiWindow.Activate();return;}midiWindow=new Form{Text="Agent Looper / MIDI",Size=new Size(440,220),FormBorderStyle=FormBorderStyle.FixedToolWindow,StartPosition=FormStartPosition.CenterParent,ShowInTaskbar=false,BackColor=Skin.Ink,ForeColor=Color.WhiteSmoke,Font=Font};var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),WrapContents=true};midiWindow.Controls.Add(flow);flow.Controls.Add(new Label{Text="INPUT",Width=390,Height=18,ForeColor=Skin.Muted});var devices=new StudioChoice{Width=390,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Skin.Panel,ForeColor=Color.WhiteSmoke,FlatStyle=FlatStyle.Flat};devices.Items.Add("OFF");string[] names=MidiInput.Names();foreach(string name in names)devices.Items.Add(name);devices.SelectedIndex=Math.Max(0,Array.IndexOf(names,midiMap.DeviceName)+1);devices.SelectedIndexChanged+=(s,e)=>{try{if(midiInput!=null){midiInput.Dispose();midiInput=null;}midiMap.ResetEdges();midiMap.DeviceName=devices.SelectedIndex>0?devices.SelectedItem.ToString():"";if(devices.SelectedIndex>0)midiInput=new MidiInput(devices.SelectedIndex-1);SaveMidi();}catch(Exception ex){status.Text=ex.Message;if(midiInfo!=null)midiInfo.Text=ex.Message;}};flow.Controls.Add(devices);midiTarget=new StudioChoice{Width=190,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Skin.Panel,ForeColor=Color.WhiteSmoke,FlatStyle=FlatStyle.Flat,Margin=new Padding(3,12,3,3)};foreach(string action in midiButtons.Keys)midiTarget.Items.Add(action);if(midiTarget.Items.Count>0)midiTarget.SelectedIndex=0;flow.Controls.Add(midiTarget);var learn=Btn("LEARN",()=>LearnMidi(midiTarget.SelectedItem.ToString()));learn.Margin=new Padding(3,8,3,3);flow.Controls.Add(learn);var clear=Btn("CLEAR",()=>{if(midiTarget.SelectedItem!=null){midiMap.Bindings.Remove(midiTarget.SelectedItem.ToString());SaveMidi();midiInfo.Text="CLEARED";}});clear.Size=new Size(75,32);clear.Margin=new Padding(3,8,3,3);flow.Controls.Add(clear);midiInfo=new Label{Text="",Width=390,Height=30,ForeColor=Skin.Mint};flow.Controls.Add(midiInfo);midiWindow.FormClosed+=(s,e)=>{midiMap.LearnTarget=null;midiInfo=null;midiTarget=null;};midiWindow.Show(this);}
 void CloseMidi(){if(midiWindow!=null&&!midiWindow.IsDisposed)midiWindow.Close();if(midiInput!=null){midiInput.Dispose();midiInput=null;}}
}
}



